// Additional benchmark drivers use real injected sources and warmed queries. They are
// enabled by --benchmark-scenarios and --benchmark-queries. Ordinary cold/retention
// samples stay isolated from their additional warmed work and measurements.
internal static class ServerRuntimeScenarios
{
    internal static string Extend(string source,string language)
    {
        string Insert(string before,string content)
        {
            if(!source.Contains(before,StringComparison.Ordinal))throw new InvalidOperationException("Missing scenario insertion: "+language);
            return source.Replace(before,content+"\n"+before,StringComparison.Ordinal);
        }
        switch(language)
        {
            case "csharp":
                source=Insert(" public static void Run",CSharp);
                return Insert("Console.WriteLine(JsonSerializer.Serialize(new{cold_ms", "Scenarios(a,k=>table.Get(k).Id,count);");
            case "java":
                source=Insert(" public static void main",Java);
                return Insert("sink=sum;", "scenarios(a,s,k->table.get(k).getId(),count);");
            case "go":
                source=source.Replace("\"testing\";\"time\"", "\"testing\";\"time\";\"sync\"");
                source=Insert("func TestBenchmarkProcess",Go);
                return Insert("bytes,_:=json.Marshal", "scenarios(t,args,s,func(k int)int32{row,e:=table.Get(int32(k));if e!=nil{panic(e)};return row.Id()},count);");
            case "cpp":
                source="#include <thread>\n"+source;
                source=Insert("int main(int,char** a)",Cpp);
                return Insert("t=Clock::now();s.reset();", "scenarios(a,s,count);");
            case "rust":
                source=Insert("fn main(){",Rust);
                return Insert("t=Instant::now();drop(s);", "scenarios(&a,&s,count);");
            case "typescript":
                source=TypeScript+"\n"+source;
                return Insert("setImmediate(()=>console.log", "scenarios(a,s,k=>table.get(k).Id,count);");
            case "lua":
                source=Lua+"\n"+source;
                return Insert("print(string.format('{\"cold_ms\"", "scenarios(arg,s,function(k)return view.get(k).Id end,count);");
            default:throw new ArgumentException(language);
        }
    }
    internal static string ExtendQueries(string source,string language)
    {
        var replacement=language switch {
            "csharp"=>("new[]{\"Bench\"}","new[]{\"Bench\",\"Combo\"}"),
            "java"=>("List.of(\"Bench\")","List.of(\"Bench\",\"Combo\")"),
            "go"=>("[]string{\"Bench\"}","[]string{\"Bench\",\"Combo\"}"),
            "cpp"=>("std::vector<std::string>{\"Bench\"}","std::vector<std::string>{\"Bench\",\"Combo\"}"),
            "rust"=>("vec![\"Bench\".into()]","vec![\"Bench\".into(),\"Combo\".into()]"),
            "typescript"=>("['Bench']","['Bench','Combo']"),
            "lua"=>("{'Bench'}","{'Bench','Combo'}"),_=>throw new ArgumentException(language)};
        if(!source.Contains(replacement.Item1,StringComparison.Ordinal))throw new InvalidOperationException("Missing query selection: "+language);
        source=source.Replace(replacement.Item1,replacement.Item2,StringComparison.Ordinal);
        void Insert(string before,string value){if(!source.Contains(before,StringComparison.Ordinal))throw new InvalidOperationException("Missing query insertion: "+language);source=source.Replace(before,value+"\n"+before,StringComparison.Ordinal);}
        switch(language)
        {
            case "csharp":Insert(" public static void Run",CSharpQueries);Insert("Console.WriteLine(JsonSerializer.Serialize(new{cold_ms","Queries(a,snapshot);");break;
            case "java":Insert(" public static void main",JavaQueries);Insert("sink=sum;","queries(a,s);");break;
            case "go":Insert("func TestBenchmarkProcess",GoQueries);Insert("bytes,_:=json.Marshal","queries(t,args,s);");break;
            case "cpp":Insert("int main(int,char** a)",CppQueries);Insert("t=Clock::now();s.reset();","queries(a,s);");break;
            case "rust":Insert("fn main(){",RustQueries);Insert("t=Instant::now();drop(s);","queries(&a,&s);");break;
            case "typescript":source=TypeScriptQueries+"\n"+source;Insert("setImmediate(()=>console.log","queries(a,s);");break;
            case "lua":source=LuaQueries+"\n"+source;Insert("print(string.format('{\"cold_ms\"","queries(arg,s);");break;
        }
        return source;
    }
    private const string CSharpQueries="""
 static void Queries(string[] a,Snapshot snapshot){
  void Measure(string kind,Func<int,long> query,long expected){for(int i=0;i<20000;i++)query(i);var samples=new double[1000];long before=GC.GetAllocatedBytesForCurrentThread(),sum=0;for(int b=0;b<1000;b++){long start=Stopwatch.GetTimestamp();for(int i=0;i<100;i++)sum+=query(b*100+i);samples[b]=(Stopwatch.GetTimestamp()-start)*1e9/Stopwatch.Frequency/100;}long delta=GC.GetAllocatedBytesForCurrentThread()-before;if(sum!=expected)throw new Exception("Query checksum: "+kind);double average=0;foreach(double sample in samples)average+=sample/samples.Length;Array.Sort(samples);Console.WriteLine(JsonSerializer.Serialize(new{scenario="query",kind,queries=100000,mean_ns=average,queries_per_second=1e9/average,p50_ns=samples[500],p95_ns=samples[950],p99_ns=samples[990],allocation_kind="thread-bytes",allocation_delta=delta,checksum=sum}));}
  var table=snapshot.GetBenchTable();var combo=snapshot.GetComboTable();combo.Load("east",1);combo.Load("east",2);var row=table.Get(1);row.LoadPeer();
  ConfigManifest Decode(string text)=>JsonSerializer.Deserialize<ConfigManifest>(text,new JsonSerializerOptions{IncludeFields=true})!;
  using var owner=new Manager(ZrConfig.Models.ServerCatalog.Instance,Decode);var current=owner.Reload(new FileConfigSource(a[0]),new PreparationOptions(preferJson:a[1]=="json",mode:LoadMode.LazyRowsOnAccess,selectedTables:new[]{"Bench"})).Snapshot;
  Measure("primary-hit",i=>table.Get(i%2+1).Id,150000);Measure("primary-miss",i=>table.TryGet(-i-1).HasValue?0:1,100000);Measure("composite-hit",i=>combo.Get("east",i%2+1).Id,150000);Measure("group",i=>table.FindByGroup(i%2==0?0:-1).Count,long.Parse(a[4])/100*50000);Measure("reference",i=>row.GetPeer()!.Value.Id,200000);Measure("acquire",i=>ReferenceEquals(owner.AcquireSnapshot(),current)?1:0,100000);
 }
""";
    private const string JavaQueries="""
 static void measureQuery(String kind,java.util.function.IntToLongFunction query,long expected){for(int i=0;i<20000;i++)sink=query.applyAsLong(i);double[] samples=new double[1000];var bean=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();if(!bean.isThreadAllocatedMemorySupported())throw new UnsupportedOperationException("Thread allocation counter unavailable");if(!bean.isThreadAllocatedMemoryEnabled())bean.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().getId(),before=bean.getThreadAllocatedBytes(thread),sum=0;for(int b=0;b<1000;b++){long start=System.nanoTime();for(int i=0;i<100;i++)sum+=query.applyAsLong(b*100+i);samples[b]=(System.nanoTime()-start)/100.0;}long delta=bean.getThreadAllocatedBytes(thread)-before;if(sum!=expected)throw new AssertionError("Query checksum: "+kind);double average=Arrays.stream(samples).average().orElseThrow();Arrays.sort(samples);System.out.printf(Locale.ROOT,"{\"scenario\":\"query\",\"kind\":\"%s\",\"queries\":100000,\"mean_ns\":%.6f,\"queries_per_second\":%.6f,\"p50_ns\":%.6f,\"p95_ns\":%.6f,\"p99_ns\":%.6f,\"allocation_kind\":\"thread-bytes\",\"allocation_delta\":%d,\"checksum\":%d}%n",kind,average,1e9/average,samples[500],samples[950],samples[990],delta,sum);}
 static void queries(String[] a,DataSnapshot snapshot){var token=new Cancellation();var table=snapshot.get_Bench();var combo=snapshot.get_Combo();combo.load("east",1,token);combo.load("east",2,token);var row=table.get(1);row.load_Peer();try(var owner=DataSnapshot.manager()){owner.reload(()->snapshot,token,PreparationOptions.defaults());measureQuery("primary-hit",i->table.get(i%2+1).getId(),150000);measureQuery("primary-miss",i->table.find(-i-1)==null?1:0,100000);measureQuery("composite-hit",i->combo.get("east",i%2+1).getId(),150000);measureQuery("group",i->table.findGroup_ByGroup(i%2==0?0:-1).size(),Long.parseLong(a[4])/100*50000);measureQuery("reference",i->row.get_Peer().getId(),200000);measureQuery("acquire",i->owner.acquireSnapshot()==snapshot?1:0,100000);}}
""";
