func queries(t *testing.T,a []string,snapshot *DataSnapshot){
 measure:=func(kind string,query func(int)int64,expected int64){for i:=0;i<20000;i++{query(i)};samples:=make([]float64,1000);var before,after runtime.MemStats;runtime.ReadMemStats(&before);var sum int64;for b:=range samples{start:=time.Now();for i:=0;i<100;i++{sum+=query(b*100+i)};samples[b]=float64(time.Since(start).Nanoseconds())/100};runtime.ReadMemStats(&after);if sum!=expected{t.Fatalf("Query checksum %s: %d",kind,sum)};var average float64;for _,sample:=range samples{average+=sample/float64(len(samples))};sort.Float64s(samples);encoded,encodeError:=json.Marshal(map[string]interface{}{"scenario":"query","kind":kind,"queries":100000,"mean_ns":average,"queries_per_second":1e9/average,"p50_ns":samples[500],"p95_ns":samples[950],"p99_ns":samples[990],"allocation_kind":"process-bytes","allocation_delta":after.TotalAlloc-before.TotalAlloc,"allocation_count":after.Mallocs-before.Mallocs,"checksum":sum});if encodeError!=nil{t.Fatal(encodeError)};fmt.Println(string(encoded))}
 ctx:=context.Background();table,e:=snapshot.Get_Bench();if e!=nil{t.Fatal(e)};combo,e:=snapshot.Get_Combo();if e!=nil{t.Fatal(e)};for _,id:=range []int32{1,2}{if _,e=combo.Load(ctx,"east",id);e!=nil{t.Fatal(e)}};row,e:=table.Get(1);if e!=nil{t.Fatal(e)};if _,e=row.Load_Peer(ctx);e!=nil{t.Fatal(e)};owner:=&ServerManager[DataSnapshot]{};defer owner.Close();if _,e=owner.Reload(ctx,func(context.Context)(*DataSnapshot,error){return snapshot,nil},DefaultPreparationOptions());e!=nil{t.Fatal(e)}
 measure("primary-hit",func(i int)int64{v,e:=table.Get(int32(i%2+1));if e!=nil{panic(e)};return int64(v.Id())},150000);measure("primary-miss",func(i int)int64{_,ok,e:=table.Find(int32(-i-1));if e!=nil||ok{panic("missing key")};return 1},100000);measure("composite-hit",func(i int)int64{v,e:=combo.Get("east",int32(i%2+1));if e!=nil{panic(e)};return int64(v.Id())},150000);n,_:=strconv.Atoi(a[4]);measure("group",func(i int)int64{key:=int32(0);if i%2!=0{key=-1};v,e:=table.FindGroup_ByGroup(key);if e!=nil{panic(e)};return int64(v.Len())},int64(n/100)*50000);measure("reference",func(i int)int64{v,e:=row.Get_Peer();if e!=nil{panic(e)};return int64(v.Id())},200000);measure("acquire",func(i int)int64{v,e:=owner.AcquireSnapshot();if e!=nil||v!=snapshot{panic("acquire")};return 1},100000)
}
