    private const string CSharp="""
 static void Scenarios(string[] a,Func<int,int> query,int count){
  void Emit(object value)=>Console.WriteLine(JsonSerializer.Serialize(value));
  foreach(int readers in new[]{1,4}){var sums=new long[readers];using var ready=new System.Threading.CountdownEvent(readers);using var start=new System.Threading.ManualResetEventSlim();var threads=new System.Threading.Thread[readers];for(int i=0;i<readers;i++){int slot=i;threads[i]=new System.Threading.Thread(()=>{ready.Signal();start.Wait();long sum=0;for(int j=0;j<100000;j++)sum+=query(j%count+1);sums[slot]=sum;});threads[i].Start();}ready.Wait();var clock=Stopwatch.StartNew();start.Set();foreach(var thread in threads)thread.Join();double elapsed=clock.Elapsed.TotalMilliseconds;long expected=0;for(int j=0;j<100000;j++)expected+=j%count+1;foreach(long sum in sums)if(sum!=expected)throw new Exception("Concurrent checksum");Emit(new{scenario="readers",readers,queries_per_reader=100000,elapsed_ms=elapsed,checksum=expected*readers});}
  ConfigManifest Decode(string text)=>JsonSerializer.Deserialize<ConfigManifest>(text,new JsonSerializerOptions{IncludeFields=true})!;
  using var owner=new Manager(ZrConfig.Models.ServerCatalog.Instance,Decode);var options=new PreparationOptions(preferJson:a[1]=="json",mode:LoadMode.LazyRowsOnAccess,selectedTables:new[]{"Bench"});var file=new FileConfigSource(a[0]);var old=owner.Reload(file,options).Snapshot;
  foreach(string profile in new[]{"normal","delayed","failed"}){int reads=0;byte[] Read(string path,System.Threading.CancellationToken token){reads++;if(profile=="delayed")System.Threading.Thread.Sleep(1);if(profile=="failed"&&reads==2)throw new System.IO.IOException("controlled read failure");return file.Read(path,token);}var source=new DelegateSyncConfigSource(Read,(path,token)=>ConfigOperation<byte[]>.FromResult(Read(path,token)));var clock=Stopwatch.StartNew();bool failed=false;try{using var prepared=owner.Prepare(source,options);}catch(ConfigException error)when(error.Code==ErrorCode.ReadFailed){failed=true;}if(failed!=(profile=="failed")||!ReferenceEquals(old,owner.AcquireSnapshot())||owner.GetStatus().Generation!=1||owner.ActivePreparationCount!=0)throw new Exception("Source failure rollback");Emit(new{scenario="source",profile,reads,delay_per_read_ms=profile=="delayed"?1:0,elapsed_ms=clock.Elapsed.TotalMilliseconds,failed,preserved_current=true});}
 }
