    private const string Go="""
type scenarioSource struct{file *FileConfigSource;profile string;reads int}
func(s *scenarioSource)Read(ctx context.Context,path string,maximum int64)([]byte,error){s.reads++;if s.profile=="delayed"{time.Sleep(time.Millisecond)};if s.profile=="failed"&&s.reads==2{return nil,fmt.Errorf("controlled read failure")};return s.file.Read(ctx,path,maximum)}
func scenarios(t *testing.T,a []string,snapshot *DataSnapshot,query func(int)int32,count int){
 emit:=func(value interface{}){bytes,e:=json.Marshal(value);if e!=nil{t.Fatal(e)};fmt.Println(string(bytes))}
 for _,readers:=range []int{1,4}{sums:=make([]int64,readers);var ready,done sync.WaitGroup;ready.Add(readers);done.Add(readers);start:=make(chan struct{});for i:=0;i<readers;i++{go func(slot int){defer done.Done();ready.Done();<-start;var sum int64;for j:=0;j<100000;j++{sum+=int64(query(j%count+1))};sums[slot]=sum}(i)};ready.Wait();now:=time.Now();close(start);done.Wait();elapsed:=float64(time.Since(now))/float64(time.Millisecond);var expected int64;for j:=0;j<100000;j++{expected+=int64(j%count+1)};for _,sum:=range sums{if sum!=expected{t.Fatal("Concurrent checksum")}};emit(map[string]interface{}{"scenario":"readers","readers":readers,"queries_per_reader":100000,"elapsed_ms":elapsed,"checksum":expected*int64(readers)})}
 ctx:=context.Background();file,e:=NewFileConfigSource(a[0]);if e!=nil{t.Fatal(e)};owner:=&ServerManager[DataSnapshot]{};defer owner.Close();options:=PreparationOptions{Timeout:5*time.Minute,CandidateLifetime:5*time.Minute};if _,e=owner.Reload(ctx,func(context.Context)(*DataSnapshot,error){return snapshot,nil},options);e!=nil{t.Fatal(e)}
 for _,profile:=range []string{"normal","delayed","failed"}{source:=&scenarioSource{file:file,profile:profile};now:=time.Now();prepared,e:=owner.Prepare(ctx,func(token context.Context)(*DataSnapshot,error){return LoadDataSource(token,source,LoadPlan{Mode:LazyRowsOnAccess,Tables:[]string{"Bench"},PreferJSON:a[1]=="json"})},options);if prepared!=nil{prepared.Discard()};failed:=e!=nil;if failed{if fault,ok:=e.(*ConfigError);!ok||fault.Code!=ReadFailed{t.Fatal(e)}};current,_:=owner.AcquireSnapshot();if failed!=(profile=="failed")||current!=snapshot||owner.Status().Generation!=1{t.Fatal("Source rollback")};delay:=0;if profile=="delayed"{delay=1};emit(map[string]interface{}{"scenario":"source","profile":profile,"reads":source.reads,"delay_per_read_ms":delay,"elapsed_ms":float64(time.Since(now))/float64(time.Millisecond),"failed":failed,"preserved_current":true})}
}
""";
    private const string Cpp="""
struct ScenarioSource:ConfigSource{FileConfigSource file;std::string profile;int reads=0;ScenarioSource(const char* root,std::string kind):file(root),profile(std::move(kind)){}std::vector<std::uint8_t> read(const std::string& path,std::uint64_t maximum,const Cancellation& token)override{++reads;if(profile=="delayed")std::this_thread::sleep_for(std::chrono::milliseconds(1));if(profile=="failed"&&reads==2)throw ConfigError(ErrorCode::ReadFailed,"controlled read failure");return file.read(path,maximum,token);}};
void scenarios(char** a,const std::shared_ptr<const data::Snapshot>& snapshot,int count){
 for(int readers:{1,4}){std::vector<std::int64_t>sums(readers);std::mutex gate;std::condition_variable changed;int ready=0;bool started=false;std::vector<std::thread> threads;for(int i=0;i<readers;++i)threads.emplace_back([&,i]{{std::unique_lock<std::mutex> lock(gate);++ready;changed.notify_all();changed.wait(lock,[&]{return started;});}std::int64_t sum=0;for(int j=0;j<100000;++j)sum+=snapshot->get_Bench(j%count+1).Id();sums[i]=sum;});{std::unique_lock<std::mutex> lock(gate);changed.wait(lock,[&]{return ready==readers;});}auto now=Clock::now();{std::lock_guard<std::mutex> lock(gate);started=true;}changed.notify_all();for(auto& thread:threads)thread.join();double elapsed=ms(now);std::int64_t expected=0;for(int j=0;j<100000;++j)expected+=j%count+1;for(auto sum:sums)if(sum!=expected)throw std::logic_error("Concurrent checksum");std::cout<<"{\"scenario\":\"readers\",\"readers\":"<<readers<<",\"queries_per_reader\":100000,\"elapsed_ms\":"<<elapsed<<",\"checksum\":"<<expected*readers<<"}\n";}
 Cancellation token;ServerManager<data::Snapshot> owner;owner.reload([&]{return snapshot;},token);LoadPlan plan;plan.mode=LoadMode::LazyRowsOnAccess;plan.tables=std::vector<std::string>{"Bench"};plan.prefer_json=std::string(a[2])=="json";
 for(const std::string profile:{"normal","delayed","failed"}){ScenarioSource source(a[1],profile);auto now=Clock::now();bool failed=false;try{auto prepared=owner.prepare([&]{return data::Snapshot::load(source,LoadSettings(plan),token);},token);}catch(const ConfigError& error){if(error.code!=ErrorCode::ReadFailed)throw;failed=true;}if(failed!=(profile=="failed")||owner.acquire_snapshot()!=snapshot||owner.status().generation!=1||owner.diagnostics().active_preparations!=0)throw std::logic_error("Source rollback");std::cout<<"{\"scenario\":\"source\",\"profile\":\""<<profile<<"\",\"reads\":"<<source.reads<<",\"delay_per_read_ms\":"<<(profile=="delayed"?1:0)<<",\"elapsed_ms\":"<<ms(now)<<",\"failed\":"<<(failed?"true":"false")<<",\"preserved_current\":true}\n";}
}
""";
    private const string Rust="""
struct ScenarioSource{file:FileConfigSource,profile:&'static str,reads:std::cell::Cell<usize>}
impl ConfigSource for ScenarioSource{fn read(&self,path:&str,maximum:u64,token:&Cancellation)->ServerResult<Vec<u8>>{self.reads.set(self.reads.get()+1);if self.profile=="delayed"{std::thread::sleep(std::time::Duration::from_millis(1));}if self.profile=="failed"&&self.reads.get()==2{return Err(ConfigError::new(ErrorCode::ReadFailed,"controlled read failure"))}self.file.read(path,maximum,token)}}
fn scenarios(a:&[String],snapshot:&std::sync::Arc<zrconfig::data::Snapshot>,count:usize){
 for readers in [1,4]{let ready=std::sync::Arc::new(std::sync::Barrier::new(readers+1));let start=std::sync::Arc::new(std::sync::Barrier::new(readers+1));let mut threads=Vec::new();for _ in 0..readers{let ready=ready.clone();let start=start.clone();let snapshot=snapshot.clone();threads.push(std::thread::spawn(move||{ready.wait();start.wait();let mut sum=0i64;for j in 0..100000{sum+=snapshot.get_Bench((j%count+1)as i32).unwrap().get_Id()as i64;}sum}));}ready.wait();let now=Instant::now();start.wait();let sums:Vec<_>=threads.into_iter().map(|thread|thread.join().unwrap()).collect();let elapsed=ms(now);let expected=(0..100000).map(|j|(j%count+1)as i64).sum::<i64>();for sum in sums{assert_eq!(sum,expected);}println!("{{\"scenario\":\"readers\",\"readers\":{},\"queries_per_reader\":100000,\"elapsed_ms\":{},\"checksum\":{}}}",readers,elapsed,expected*readers as i64);}
 let token=Cancellation::default();let owner=zrconfig::data::Snapshot::manager();let options=PreparationOptions::default();owner.reload(||Ok(snapshot.clone()),&token,options).unwrap();let settings=LoadSettings::new(LoadPlan{mode:LoadMode::LazyRowsOnAccess,tables:Some(vec!["Bench".to_owned()]),prefer_json:a[2]=="json",..LoadPlan::default()});
 for profile in ["normal","delayed","failed"]{let source=ScenarioSource{file:FileConfigSource::new(std::path::Path::new(&a[1])),profile,reads:std::cell::Cell::new(0)};let now=Instant::now();let result=owner.prepare(||zrconfig::data::Snapshot::load_source(&source,&settings,&token),&token,options);let failed=match result{Ok(_)=>false,Err(error)=>{assert_eq!(error.code,ErrorCode::ReadFailed);true}};assert_eq!(failed,profile=="failed");assert!(std::sync::Arc::ptr_eq(&owner.acquire_snapshot().unwrap(),snapshot));assert_eq!(owner.status().unwrap().generation,1);assert_eq!(owner.diagnostics().unwrap().active_preparations,0);println!("{{\"scenario\":\"source\",\"profile\":\"{}\",\"reads\":{},\"delay_per_read_ms\":{},\"elapsed_ms\":{},\"failed\":{},\"preserved_current\":true}}",profile,source.reads.get(),if profile=="delayed"{1}else{0},ms(now),failed);}
}
""";
