 const R=require(require('path').join(process.argv[2],'dist/runtime.js'));let sum=0;let now=performance.now();for(let j=0;j<100000;j++)sum+=query(j%count+1);const elapsed=performance.now()-now;let expected=0;for(let j=0;j<100000;j++)expected+=j%count+1;if(sum!==expected)throw Error('Reader checksum');console.log(JSON.stringify({scenario:'readers',readers:1,queries_per_reader:100000,elapsed_ms:elapsed,checksum:sum,threaded:false}));
